+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+.radio-label input[type="radio"] {
+    accent-color: #0d6efd;
+}
+
+/* ───── Appearance Preview ───── */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 2px dashed #dee2e6;
+    border-radius: 8px;
+    transition: all 0.3s ease;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+    margin-bottom: 0.5rem;
