+.preview-theme-dark .preview-card {
+    background: #16213e;
+    color: #ccc;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-theme-system {
+    background: #f0f4f8;
+    color: #333;
+}
+
+/* Font size variants */
+.preview-font-small { font-size: 0.8rem; }
+.preview-font-medium { font-size: 1rem; }
+.preview-font-large { font-size: 1.2rem; }
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.75rem;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.4rem;
+}
